question.solution:
def test_case(fn):
    fn._is_test = True
    return fn


def collect_tests(namespace):
    found = []
    for name, value in namespace.items():
        if name.startswith('test_') and callable(value):
            found.append((name, value))
    found.sort(key=lambda item: item[0])
    return found


def run_all(namespace):
    passed = failed = 0
    errors = []
    for name, fn in collect_tests(namespace):
        try:
            fn()
        except AssertionError as exc:
            failed += 1
            errors.append(f'{name}: 断言失败 {exc}')
        except Exception as exc:
            failed += 1
            errors.append(f'{name}: {type(exc).__name__} {exc}')
        else:
            passed += 1
    return {'passed': passed, 'failed': failed, 'errors': errors}


@test_case
def test_add():
    assert 1 + 1 == 2


@test_case
def test_upper():
    assert 'abc'.upper() == 'ABC'


@test_case
def test_故意失败():
    assert 2 + 2 == 5, '四则运算错了'


def helper():
    return 1


namespace = {k: v for k, v in globals().items() if getattr(v, '_is_test', False)}
result = run_all(namespace)
print(result)
